// Placeholder asset generator (docs/DESIGN.md §11): flat-color PNG blocks
// with a 1px darker border, written with only node:zlib (no image deps).
// Regenerated by `npm run assets` before dev/build, so the PNGs stay gitignored.
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { deflateSync } from "node:zlib";

const ASSETS_DIR = join(dirname(fileURLToPath(import.meta.url)), "..", "public", "assets");

const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();

function crc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function chunk(type, data) {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type, "ascii"), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body));
  return Buffer.concat([len, body, crc]);
}

function png(width, height, pixels) {
  const stride = width * 3;
  const raw = Buffer.alloc((stride + 1) * height);
  for (let y = 0; y < height; y++) {
    raw[y * (stride + 1)] = 0; // filter: none
    pixels.copy(raw, y * (stride + 1) + 1, y * stride, (y + 1) * stride);
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 2; // color type: RGB
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", ihdr),
    chunk("IDAT", deflateSync(raw)),
    chunk("IEND", Buffer.alloc(0)),
  ]);
}

function hexToRgb(hex) {
  return [
    parseInt(hex.slice(1, 3), 16),
    parseInt(hex.slice(3, 5), 16),
    parseInt(hex.slice(5, 7), 16),
  ];
}

function paintRect(buf, w, x0, y0, rw, rh, rgb) {
  for (let y = y0; y < y0 + rh; y++) {
    for (let x = x0; x < x0 + rw; x++) {
      const i = (y * w + x) * 3;
      buf[i] = rgb[0];
      buf[i + 1] = rgb[1];
      buf[i + 2] = rgb[2];
    }
  }
}

function image(width, height, paint) {
  const buf = Buffer.alloc(width * height * 3);
  paint((x, y, rw, rh, hex) => paintRect(buf, width, x, y, rw, rh, hexToRgb(hex)));
  return png(width, height, buf);
}

// Tile ids are 1-based in Phaser data maps; index i below = tile id i+1.
// Order must match the T map in FieldScene.
const TILES = [
  ["#3a4634", "#2c3628"], // 1 grass
  ["#6a5a44", "#574a38"], // 2 road
  ["#3a3f4a", "#23262e"], // 3 building
  ["#2c4a5a", "#233c4a"], // 4 water
  ["#2f4a2c", "#20331e"], // 5 tree
  ["#4a4b52", "#34353c"], // 6 cliff
  ["#756a4e", "#5f563f"], // 7 sand (练武场)
  ["#23262e", "#15171d"], // 8 town wall
  ["#5c5e66", "#43454c"], // 9 well
  ["#43464e", "#373a41"], // 10 town ground
];

function bordered(width, height, fill, edge) {
  return image(width, height, (rect) => {
    rect(0, 0, width, height, fill);
    rect(0, 0, width, 1, edge);
    rect(0, height - 1, width, 1, edge);
    rect(0, 0, 1, height, edge);
    rect(width - 1, 0, 1, height, edge);
  });
}

mkdirSync(ASSETS_DIR, { recursive: true });

const tiles = image(TILES.length * 16, 16, (rect) => {
  TILES.forEach(([fill, edge], i) => {
    rect(i * 16, 0, 16, 16, fill);
    rect(i * 16, 0, 16, 1, edge);
    rect(i * 16, 15, 16, 1, edge);
    rect(i * 16, 0, 1, 16, edge);
    rect(i * 16 + 15, 0, 1, 16, edge);
  });
});
writeFileSync(join(ASSETS_DIR, "tiles.png"), tiles);

const player = bordered(16, 16, "#e8e6e0", "#23262e");
writeFileSync(join(ASSETS_DIR, "player.png"), player);

// Mob blocks (docs/DESIGN.md §4): wolf gray, bandit brown, boss dark red.
const MOBS = [
  ["wolf", "#7d8590", "#565c66"],
  ["bandit", "#8a6a4a", "#5f4a33"],
  ["boss", "#7a3f3f", "#52282a"],
];
for (const [name, fill, edge] of MOBS) {
  writeFileSync(join(ASSETS_DIR, `${name}.png`), bordered(16, 16, fill, edge));
}

console.log(
  `generated: tiles.png (${TILES.length} tiles), player.png, ${MOBS.map((m) => `${m[0]}.png`).join(", ")} -> ${ASSETS_DIR}`,
);
